function t(key, vars) {
  const row = I18N[key];
  const idx = Object.keys(LANGS).indexOf(STATE.lang);
  let s = row ? (row[idx] || row[1] || row[0]) : key;
  if (vars) for (const k in vars) s = s.split('{' + k + '}').join(vars[k]);
  return s;
}
/* Velg riktig språk fra et objekt {nb, en, fr, nl}; faller tilbake til engelsk, så norsk. */
function L(o) { return typeof o === 'string' ? o : (o[STATE.lang] || (STATE.lang !== 'nb' && o.en) || o.nb); }
